# Bám sách: trang 42–43 + đáp án + Mini dictionary unit 19. Không chép nguyên văn.
theory = (
 H("A", "Beginning and ending", "Bắt đầu và kết thúc")
 + P("The book presents these verbs in a table with the nouns they typically go with.", "Sách trình bày các động từ này trong bảng, kèm danh từ thường đi cùng.")
 + table(["Phrasal verb + typical nouns", "Meaning"], ["Phrasal verb + danh từ hay đi kèm", "Nghĩa"], [
    ("new businesses / political movements / buildings <b>spring up</b>", "", "suddenly appear or start to exist", "đột nhiên xuất hiện"),
    ("new buildings / factories / cafés <b>sprout up</b>", "", "suddenly appear or start to exist", "đột nhiên mọc lên"),
    ("<b>open up</b> opportunities/possibilities, or they <b>open up</b>", "", "make possible or become possible", "mở ra, trở nên khả thi"),
    ("<b>break up</b> a party (or the party <b>breaks up</b>)", "", "it finishes and everyone goes home", "kết thúc, mọi người ra về"),
    ("<b>finish with</b> a magazine / scissors / salt", "", "no longer need it", "không cần nữa, dùng xong"),
    ("prices or a trend <b>bottom out</b>", "", "stop falling and stay at the lowest point", "xuống mức thấp rồi chững lại"),
    ("a game / match / anger / protest / conflict <b>peters out</b>", "", "slowly get weaker and then stop completely", "yếu dần rồi tắt hẳn"),
    ("<b>wind up</b> a business / interview / meeting", "", "end", "kết thúc"),
 ])
 + P("Note: <b>peter out</b> is unusual because ‘peter’ does not exist as a verb on its own.", "Lưu ý: <b>peter out</b> đặc biệt vì ‘peter’ không tồn tại như một động từ riêng.")
 + H("B", "Helping and hindering progress", "Thúc đẩy và cản trở tiến triển")
 + P("Several people answer the question ‘How is your business going?’", "Nhiều người trả lời câu hỏi ‘Việc kinh doanh của bạn thế nào?’")
 + T([
    ("<b>dry up</b>", "They had to stop because their cheap supply of materials came to an end.", "Họ phải dừng vì nguồn vật liệu giá rẻ đã cạn."),
    ("<b>fall apart</b>", "Things have stopped working well since the new manager came.", "Mọi việc trục trặc từ khi quản lý mới đến."),
    ("<b>run out</b>", "They can do nothing now because there is no money left.", "Họ không làm được gì vì hết tiền."),
    ("<b>press on</b>", "They are continuing in a determined way despite many problems (see Unit 13).", "Họ vẫn kiên trì tiếp tục dù gặp nhiều vấn đề (xem bài 13)."),
    ("<b>magic away</b>", "The new HR person made their staffing problems disappear as if by magic.", "Người phụ trách nhân sự mới làm các vấn đề nhân sự biến mất như có phép."),
    ("<b>get up to</b>", "They reached the third stage of their plan but have made little progress since.", "Họ đã đến giai đoạn ba của kế hoạch nhưng từ đó tiến triển ít."),
    ("<b>hang on to</b>", "A PA has improved things a lot, so they hope to keep her.", "Cô trợ lý giúp mọi việc tốt lên nhiều nên họ mong giữ được cô."),
    ("<b>whittle away (at)</b>", "The CEO is gradually reducing the authority of middle managers.", "Giám đốc điều hành đang dần bào mòn quyền hạn của các quản lý cấp trung."),
 ])
 + NOTE("<b>Exercise 19.4 – word play</b>: a clock is <b>wound up</b>; a sprout is a vegetable (<b>sprout up</b>); dry cleaners <b>press</b> clothes (<b>press on</b>); a trampoline has <b>springs</b> (<b>spring up</b>); training shoes are for <b>running</b> (<b>run out of</b> money). <b>Open up</b> and <b>break up</b> can be used with or without an object (19.1).",
        "<b>Bài 19.4 – chơi chữ</b>: đồng hồ được <b>lên dây</b> (wind up); sprout là bắp cải tí hon (<b>sprout up</b>); tiệm giặt khô <b>là ủi</b> quần áo (<b>press on</b>); bạt nhún có <b>lò xo</b> (<b>spring up</b>); giày thể thao để <b>chạy</b> (<b>run out of</b> money). <b>Open up</b> và <b>break up</b> dùng được có hoặc không có tân ngữ (19.1).")
)
